INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_8_0','琵琶亭二绝','周紫芝','北宋末','捍拨难传不尽情，
琵声裁尽继琶声。
风流扫地无人说，
只有空江旧月明。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_1','陪李使君登庾楼是日云雾不见淮山二首','周紫芝','北宋末','跨江云梦不胜宽，
楼在江声汹涌间。
试看坐中寻得句，
说君眼力尽时山。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_2','陪李使君登庾楼是日云雾不见淮山二首','周紫芝','北宋末','楼前江水看镕银，
江外淮山色未分。
安得长驱鳄鱼手，
为开南岳岭头云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_3','九江赵倅新作环季亭','周紫芝','北宋末','小携樽酒作清游，
寻得方壶最上头。
山在断霞明处碧，
江从白鸟去边流。
苦无健句争天巧，
赖有新亭慰客愁。
他日东南论胜地，
未应只数庾公楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_4','题东林香山像','周紫芝','北宋末','大唐受历三百年，
文士辈出俱可传。
情虽妩媚中骨鲠，
当时只有香山贤。
香山年少谪湓浦，
卧听琵琶心独苦。
想得回舟夜半时，
半湿青衫泪如雨。
别来江月几番圆，
黄芦苦竹空凄然。
风流扫地那复有，
但见东风吹白髯。
可怜画手无前辈，
欲倩虎头呼不起。
琼枝玉树了无踪，
铁拨鹍弦何用尔。
明朝一舸下浔阳，
月明依旧空江水。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_5','借书','周紫芝','北宋末','牢落偏州少士夫，
一鸱求借是书无。
道山堂外长廊下，
黄卷如云记石渠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_6','课吏抄书戏作','周紫芝','北宋末','雪花飞上白髭须，
茧纸犹抄细字书。
莫笑老翁儿戏子，
政缘长日要销除。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_7','湖亭怀旧三绝','周紫芝','北宋末','铃索无声讼牒空，
妙香寮外水冥濛。
长安故旧如相问，
今在江西道院中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_8','湖亭怀旧三绝','周紫芝','北宋末','校书天禄想诸郎，
应在蓬山语昼长。
记得去年秋七月，
日斜香转曝书廊。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_9','湖亭怀旧三绝','周紫芝','北宋末','白头武部最风流，
便是汝南陈太邱。
折角乌巾人似画，
与谁同伴两山游。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_10','沈季卿出元具茨王相山诗卷相示两翁虽存没异途而均为不偶读之良增慨叹为题轴尾','周紫芝','北宋末','沈郎带减不胜衣，
瘦甚由来政坐诗。
试数交游尽前辈，
便知文采照当时。
子猷何处寻脩竹，
漫叟今谁吊旧祠。
人似浮云忽吹散，
老夫虽健鬓成丝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_11','寄题陈医安乐堂','周紫芝','北宋末','六尘欲要净三摩，
辛苦修行奈老何。
只得四休安乐法，
一身受用已为多。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_12','寄题陈医安乐堂','周紫芝','北宋末','自笑区区老倦游，
庐山今是我菟裘。
暮年欲觅安心法，
他日敲门问四休。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_13','送陈鄂州','周紫芝','北宋末','旧识君家小仲容，
步兵今复此相同。
谁教楚楚青云器，
来照鬖鬖白雪翁。
庐阜故山休入望，
武昌官柳正摇风。
只应黄霸归朝日，
已在天边尺一中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_14','窗明','周紫芝','北宋末','窗明有斜日，
几静无一尘。
向后有馀恨，
乱鸦来聒人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_15','病起步至湖亭三首','周紫芝','北宋末','雨从今日十分晴，
病后春应一倍增。
著地已无残岁雪，
挂檐犹有上元灯。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_16','病起步至湖亭三首','周紫芝','北宋末','薄罗初欲换单衣，
社肉裁分燕又归。
唤得春来却催去，
满庭红雨杏花飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_17','病起步至湖亭三首','周紫芝','北宋末','病馀犹著杖藜扶，
临水依然一老夫。
不用苦烧红蜡烛，
桃花解笑白髭须。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_18','吊梅二首','周紫芝','北宋末','飞尽江南泣雨枝，
韵高犹共雨相宜。
洗妆只有唇红在，
也胜桃花好面皮。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_19','吊梅二首','周紫芝','北宋末','伤心不见玉扶疏，
丹杏缥桃亦甚都。
只恐此君零落后，
馀芳要自不如渠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_20','春日连雨湖水大至二首','周紫芝','北宋末','楚地春三月，
他乡客二毛。
愁怀须著酒，
寒力尚欺袍。
细雨淹花湿，
颠风拍浪高。
昨朝红药柱，
今日整渔舠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_21','春日连雨湖水大至二首','周紫芝','北宋末','白雨鸣珠琲，
春江灌玉壶。
漫郎回小艇，
摩诘画新图。
山近醒愁眼，
州闲养病躯。
如何樽酒地，
更与看南湖。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_22','秦少保生日诗三首','周紫芝','北宋末','岁当作噩律始催，
杓携龙角星纪回。
祥云下覆穷九垓，
帝车御极云旗排。
夜色清润明三台，
昴精叱驭天上来。
上帝欲遣清风埃，
汉家双阙高崔嵬。
日趋龙尾朝蓬莱，
父师有鼎调盐梅。
公赞庙画众允谐，
龙颜一笑天欢咍。
虎皮蒙甲卷不开，
白玉彫俎尊有雷。
五风十雨无烟霾，
爟火夜上通天台。
礼成一代谁可偕，
功高欲报帝所怀。
大用永配德与才，
寿庙祝之言可该，
拍肩俱愿齐洪崖。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_23','秦少保生日诗三首','周紫芝','北宋末','跨鳌昔上环州山，
恍如梦见非人间。
黄金作屋碧玉椽，
灵芝仙草香流泉。
琅函玉轴架插天，
神龙守钥秘不传。
天书错落御墨鲜，
泥金描凤宝带缠。
中有紫府遐龄仙，
主张东壁宗众贤。
天风猎猎吹广寒，
霞浆酌客春昼暄。
蕊珠琴心久精妍，
灵根坚固玉鍊颜。
三官四辅谁可迁，
看公衮绣当帝前，
拾尘算劫不计年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_24','秦少保生日诗三首','周紫芝','北宋末','右文天子朝明光，
汉陛晓列千官行。
罢朝不归按霓裳，
黄门群袭御殿香。
翠盖趣驾黄微张，
日高宫树遮回廊。
侍臣进册俨在旁，
香罗覆帕牙签长。
前规尧舜后三王，
六维龟鉴策最良。
圣心自约昔未堂，
日有所就月有将。
公书万卷胸中藏，
海涵地负谁可当。
官粗住下百报忙，
独留真儒传紫皇。
茶瓯拜赐近御床，
天颜咫尺瞻龙章。
金叶旧事不足方，
人如褚马才亦常。
说定惟服宁可忘，
设施行当见庙堂。
可使风俗还轩黄，
有时问道崆峒乡。
广成之师寿百昌，
千有三百岁未央。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_25','二月二十三日遵奉圣诏出郊劝农谨赋诗一首示诸同寮','周紫芝','北宋末','星言出郊坰，
缓辔遵微涂。
陂池湛新绿，
阡陌开上腴。
春色向晼晚，
农事日已趋。
有司奉汉诏，
训辞宣帝谟。
父老数十辈，
龙钟白髯须。
扶杖前致词，
谓当极勤劬。
曩也事格斗，
今当反田庐。
农桑遂温饱，
里胥绝征诛。
兹焉不少力，
是自贻瘠臞。
椒浆酌大斗，
起坐时欢呼。
有如一日蜡，
相期悦须臾。
殷勤颇自愧，
小信殊未孚。
傥非获三登，
何以谢汝徒。
同寮数君子，
妙略怀永图。
愿言规迟暮，
共此丰岁娱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_26','次韵郭宰题妙香寮','周紫芝','北宋末','香严参鼻观，
可受郢人斤。
谁能论许事，
且炷松炉薰。
借此沈水力，
侑我棐几文。
小阁亦窈窕，
青烟散敷纷。
与人共婆娑，
此意良殷勤。
恨无博山赋，
可写蜀锦纹。
老人住江东，
来作江西云。
江湖渺归思，
先弟无馀芬。
焚香此幽事，
此外何所欣。
如人嗜昌歜，
岂复思膻荤。
令君出新语，
种学窥多闻。
但恐燕寝句，
颇惭韦使君。
更当宿残火，
薄雾看氤氲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_27','刘德秀县丞凡五和前篇仆亦五次其韵','周紫芝','北宋末','刘侯一诺重，
胜获金百斤。
秀句忽复出，
华名愧微薰。
但怜沟中断，
枉错黄金文。
君欲强推毂，
谁当为解纷。
顾我绝世好，
百念独此勤。
鹊尾得古制，
鹧鸪玩斑纹。
时从孤峦顶，
看上秋空云。
遂作小方寮，
调护留清芬。
忘言聊复尔，
念意亦可欣。
了知法界中，
清静无五荤。
倘非此地胜，
是妙数得闻。
谁知几席间，
中有造化恩。
遂此草木性，
一气蒙氤氲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_28','刘德秀县丞凡五和前篇仆亦五次其韵','周紫芝','北宋末','楚泽是鱼稻，
不论斗与斤。
老守睡足处，
饱饫闻馀薰。
时歌郢人曲，
细和湘累文。
天风一披拂，
花砌飞缤纷。
乐此尽日静，
颇无终岁勤。
刘侯过我数，
坐久衣成纹。
时惊燕梁句，
有似春空云。
千年论往事，
一炷同清芬。
有客乃如此，
我意岂不欣。
人生如草木，
鼻味殊芗荤。
海天得彼趣，
妙香吾所闻。
庶希清净化，
上答明圣恩。
从今世外乐，
可比洪崖氲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_29','刘德秀县丞凡五和前篇仆亦五次其韵','周紫芝','北宋末','蔚宗草香传，
水沈贵盈斤。
标置何必高，
有德当自薰。
士成稍蕴藉，
往往嗔斯文。
人生顾安用，
浪为此纷纷。
我静偶获趣，
君意良复勤。
摩娑辨款识，
共玩古曹纹。
青烟既司寒，
小孤方插云。
诗应神所授，
句与炉争芬。
悬知我辈事，
俗子未必欣。
不容芝兰室，
杂以蒿艾荤。
政恐千年后，
馀臭尚有闻。
惟爱青云士，
亟拜黄屋恩。
未知谁氏子，
肯对香氤氲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_30','刘德秀县丞凡五和前篇仆亦五次其韵','周紫芝','北宋末','念昔居上国，
春荠卖作斤。
那得千金囊，
可买百濯薰。
一为道院主，
坐空朱墨文。
清笳咽悲壮，
浓篆横披纷。
幽意可略喜，
老倦复小勤。
诗如水得风，
自然偶成纹。
香亦旋变灭，
颇类无心云。
丞哉两松篇，
时出水麝芬。
镂冰纳蔬肠，
争洗三韭荤。
敏手不可敌，
胜妙昔未闻。
岂不胜儿女，
呢呢相怨恩。
人生如此少，
炉烟且氤氲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_31','刘德秀县丞凡五和前篇仆亦五次其韵','周紫芝','北宋末','隐之刺五羊，
归囊香一斤。
恕投湖亭水，
内子无饭薰。
欲草廉吏传，
恨无班马文。
此风一凋落，
披靡如丝纷。
前身是香严，
宿习今尚勤。
炉烟凝室炷，
印篆缄雕纹。
嗜香犹有癖，
于世已如云。
况今花木妍，
香风度微芬。
节物岂不佳，
老况难强欣。
太常斋日多，
十饭九不荤。
唯有鼻孔香，
时于静中闻。
未知刘季和，
何如荀令君。
且当置是事，
一笑同氤氲。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_32','苏内相在黄冈尝从桃花寺僧觅茶栽移种雪堂下余始至此会岁且暮明年春得新芽试之色香味俱绝不减湖越二品宜其见赏于此老人也人言雪堂今已鞠为馆驿茶盖可知矣','周紫芝','北宋末','梅雪既扫地，
桃花露微红。
风从北苑来，
吹入茶坞中。
真香不可说，
玉色谁与同。
不知耐几汤，
成此三味功。
顾渚与日注，
名高各雌雄。
四海一大地，
所至皆春风。
物固有不幸，
乃尔殊穷通。
此品不见称，
白云空蒙茸。
移栽雪堂下，
赖有黄冈翁。
来禽青李帖，
绝世无此工。
遂使桃花名，
遍满江西东。
此老久下世，
真赏殊未逢。
只今调粥手，
乳花为谁浓。
堂今在馆驿，
树亦知何踪。
树固不足惜，
馆驿行当空。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_33','筠阳竹根枕','周紫芝','北宋末','高安老竹三尺围，
断为釜甑中可炊。
蕲州开笛不足数，
嶰谷截筒空自奇。
何如猫头未成竹，
化为霜根白如玉。
峥嵘劲节不得施，
历碌黑斑空满目。
白头老吏饱官仓，
云梦南州睡初足。
筠阳别乘一幅书，
寄我中刳两枵腹。
飘飘逸韵青衣郎，
梦中相见筠山阳。
一笑摩挲抚君背，
定教从此毋相忘。
我欲问舍无何乡，
为我往使华胥王。
人生草草两鬓霜，
要知日月壶中长。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_34','四月五日早晴二首','周紫芝','北宋末','老病犹朝朔，
华颠尚著冠。
马头收雨去，
湖面拍堤寒。
鸟作乡关语，
花如梦寐看。
晚来还倚杖，
看日下栏干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_35','四月五日早晴二首','周紫芝','北宋末','忆作西来梦，
犹堪细数程。
随云千里到，
看月五番生。
上箔蚕宜暖，
濒湖麦要晴。
天应怜病守，
有意在秋成。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_36','四月八日燕客湖亭风雨忽来颇有波澜意欣然悦之','周紫芝','北宋末','水平真欲见秋毫，
碧海无人掣巨鳌。
多谢西风卷烟雨，
肯来湖面作波涛。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_37','四月八日燕客湖亭风雨忽来颇有波澜意欣然悦之','周紫芝','北宋末','孤山十载饮湖光，
更入江西鸥鹭行。
官舍一生常近水，
前身应是水仙王。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_38','四月八日燕客湖亭风雨忽来颇有波澜意欣然悦之','周紫芝','北宋末','白雨跳珠水上鸣，
雪花吹浪酒边行。
不嗔燕子飞将去，
最爱鸬鹚睡不惊。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_39','千叶石榴盛开为赋一诗','周紫芝','北宋末','江东五月榴花红，
江西三月满花丛。
东花窘束少态度，
西花重叠红蒙茸。
谁剪燕支山下草，
乞与殷红照林杪。
移栽我欲过江东，
衔子鸿鹄今成空。
红巾半蹙为谁苦，
芳心何止千重重。
试遗红妆歌一曲，
此花此曲何由逢。
春光都无十日事，
不成夜雨还朝风。
红芳莫遣忽飞去，
断肠烟雨空溟濛。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_40','十六日对雨是日闻得濂溪地','周紫芝','北宋末','大麦结穗牛尾长，
小麦满地秋云黄。
清涟堂前今日雨，
中有庐山汤饼香。
故人唤我庐山住，
欲买茅椽近庐阜。
得田于我复何求，
只就天公觅甘澍。
天随农父与阴晴，
云共东风作朝暮。
山南山北水长流，
下田高垄禾无数。
秫堪酿酒醉不醒，
饭可充饥饱摩肚。
先生不管醉尉呵，
柱杖寻游绕山去。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_41','鼓鼕鼕行','周紫芝','北宋末','烟雨凄凄芳草渡，
隔岸鼕鼕赛神鼓。
男巫唱歌女巫舞，
蚕宜青桑麦宜土。
天下无兵三百州，
不如卖剑买汝牛。
千仓万廪汝莫爱，
富民今岁新封侯。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_42','午睡听流莺作歌','周紫芝','北宋末','拟倩花枝当绮罗，
更烦莺作缓声歌。
未残春色犹堪惜，
已老周郎奈若何。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_43','午睡听流莺作歌','周紫芝','北宋末','树里金衣不露身，
欲寻啼处了无因。
绿阴长得成何事，
遮却黄鹂最恼人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_44','午睡听流莺作歌','周紫芝','北宋末','江南草长乱啼莺，
睡足南州得细听。
最爱欲歌还欲住，
伴人如梦亦如醒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_45','寄黄超然监丞求山谷像','周紫芝','北宋末','昔人生不恨，
幸识元鲁山。
平生黄叔度，
常在梦想间。
时于绢素中，
得见冰雪颜。
晚乃客京洛，
髯孙始追攀。
眉目真似之，
典刑今未刊。
昔我在武林，
岁月不得闲。
甚欲貌公像，
归囊竟空还。
迩从同寮家，
小轴得细看。
芒鞋方释杖，
野服不著冠。
尚恐或非真，
蠹虫亦少残。
谓言君家本，
可借不作难。
愿君呼画史，
摹写来江干。
孙郎倾盖交，
臭味同芝兰。
能事亦须趣，
勿作水石悭。
君不相我请，
幽兴恐易阑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_46','次韵沈季乡题醉山堂','周紫芝','北宋末','看尽吴头楚尾山，
不嫌心似鸟知还。
可怜樽俎登临处，
正在烟云杳霭间。
地胜岂无神物护，
天教付与老翁闲。
凭栏欲唤君来语，
家住寒溪第几湾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_47','送呼延韩仲','周紫芝','北宋末','人生何苦著儒冠，
心与功名了不干。
早岁气吞云梦泽，
暮年身作灞陵官。
欲寻故国今安在，
漫醉醨樽不当欢。
老别相逢知几日，
花须句在好重看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_48','晚思','周紫芝','北宋末','落日下平芜，
回照东湖尾。
牛从何处归，
相随渡湖水。
幽人倚栏意，
得月犹未已。
白鹭知何为，
欲下还复起。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_49','送刘德秀赴官贵池','周紫芝','北宋末','刘郎人物照当时，
未上青云莫慢迟。
秋浦江山应似旧，
蓝田雁鹜不妨诗。
销魂怕作文通别，
问字谁如伯始知。
此去醉山梅欲动，
忆君同看雪前枝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_50','季卿惠诗颇寓穷愁之意作是诗勉之','周紫芝','北宋末','君有篇章配国风，
技兼鼯鼠固应穷。
但令人似千金璧，
莫恨门生一丈蓬。
北阮有生宁免俗，
蒙庄虽放亦求通。
会看黄鹄摩霄去，
未可轻投燕雀丛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_51','秋意','周紫芝','北宋末','江城木落又秋高，
归梦难成客鬓凋。
拟倩西风吹雨去，
莫来窗下打芭蕉。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_52','十月晦日郡席见鹅梨','周紫芝','北宋末','雪后新尝溅齿泉，
樽前风味固依然。
自从北郡无人到，
不见鹅梨今几年。
鲁酒谩倾犹病渴，
并刀未下已流涎。
从今莫觅张公种，
饤坐虽多不当贤。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_53','题向司户芗林图','周紫芝','北宋末','宸奎犹作麝烟浮，
便舣归航结小楼。
何处访求三岛路，
径须图画百花洲。
黄金殿里鹓鸾梦，
白鹭江头草树秋。
天上归来辋川住，
世间那有此风流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_54','腊月二十三日郡厅祷雪宿斋房赵尉灯下送蜡梅','周紫芝','北宋末','半昏灯火宿斋房，
惊见梅梢破蜡黄。
夜静月斜帘不卷，
步虚声里得花香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_55','正月十四日夜病在告雨中不寐示刘德秀','周紫芝','北宋末','雨意涔涔客梦悭，
病来无意近歌檀。
看他红袖倾春酒，
分我青灯照夜寒。
老子要非年少伴，
醉乡空愿故时欢。
悬知邺下刘公干，
犹拥书檠午夜看。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_56','题李伯时画归去来图','周紫芝','北宋末','渊明诗成无色画，
龙眠画出无声诗。
两公恐是前后身，
二妙略殊今昔时。
我顷诵诗不知处，
今乃按图俱得之。
当时想见归意好，
扁舟飏水风吹衣。
壶觞未饮入室酒，
玉色先见迎门儿。
岂无故老说情话，
尚有残菊依东篱。
云归鸟倦自有意，
欲辩已忘谁复知。
龙眠得之心应手，
笔所到处心相随。
僮奴似有傲世色，
草木亦带烟霞姿。
痴儿方办公家事，
此老自挟南亩犁。
人生异趣岂不远，
心如铁石终难移。
我今此意不自事，
老去见画空惭非。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_57','次韵范提干二首','周紫芝','北宋末','绣衮华貂侍禁宸，
忠宣遗烈在丝纶。
传家父子俱仁孝，
盖世功名孰比伦。
阀阅固知流派远，
衣冠今见典型新。
如公自是青云器，
不作刘郎问大钧。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_58','次韵范提干二首','周紫芝','北宋末','白头于世亦何能，
欲赋归来计未成。
孟博声名追往昔，
蔚宗文字慰平生。
风流易散嗟人事，
臭味相求岂世情。
欲唱清歌送行客，
不知谁是米嘉荣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_59','客梦','周紫芝','北宋末','客梦长千里，
官居已岁馀。
却愁花蕊动，
转益鬓毛疏。
山气朝朝雨，
江苞月月鱼。
匡庐早归去，
稚子可篮舆。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_60','次韵强使君见寄','周紫芝','北宋末','梦泽南州听晓鸡，
老饕于此寄朱麾。
春湖鱼上先分玉，
暗谷茶生看展旗。
酒甲江西聊可醉，
山横楚尾恨无诗。
年丰讼少知何事，
时有光阴到楚词。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_61','次韵黄叔鱼见寄','周紫芝','北宋末','江边熟睡不闻鸡，
高卧何功尚拥麾。
千里西风饱鱼蟹，
十年惊魄梦旌旗。
名惭公瑾终焉用，
人似黄香更好诗。
欲作报章无妙语，
楚歌唯有竹枝词。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_62','湖亭之胜大似江上但无芦苇二月二十日移植数十本','周紫芝','北宋末','大年著色山前雨，
摩诘无声句里秋。
已是湖山无限好，
更栽芦叶伴轻鸥。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_63','杜鹃三首','周紫芝','北宋末','甘王祠下杜鹃啼，
句句声声是说归。
安得一家三十口，
似君两翼解高飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_64','杜鹃三首','周紫芝','北宋末','千秋但有一渊明，
肯脱青衫事耦耕。
政使汉朝俱此老，
都门谁祖二疏行。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_65','杜鹃三首','周紫芝','北宋末','穷甚亦须瓶有粟，
天寒可遣妇无裈。
杜鹃不大知人意，
归计应须与细论。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_66','闻真如牡丹盛开偶忆去岁看花之会二首','周紫芝','北宋末','记得东风隔水村，
偶逢幽艳荐芳樽。
今年多病无行乐，
更怕春寒不出门。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_67','闻真如牡丹盛开偶忆去岁看花之会二首','周紫芝','北宋末','春来花草尽关愁，
风雨妨人懒出游。
不见鞓红去年面，
可怜孤负玉风流。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_68','谢王侍郎寄东仓祖送图二首','周紫芝','北宋末','都门供帐记当年，
十里旌旗暗画船。
文石班中天上客，
水晶宫里地行仙。
铃斋妙画人间见，
相府珍篇海内传。
锦轴牙签浑未识，
忽随双鲤到家边。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_69','谢王侍郎寄东仓祖送图二首','周紫芝','北宋末','抗章闻说动前旒，
分得东吴第一州。
久与衣冠为盛事，
更寻云水作遨头。
当时鹓鹭应须记，
此去湖山莫谩留。
却笑杜郎生羽翼，
但知欢喜下汀州。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_70','次韵李安州赠别','周紫芝','北宋末','老来著处便为家，
行尽江西是水涯。
诗到说归无限意，
山非吾土未应嘉。
我思故国方成恨，
君到东湖尚有花。
更欲少留听句法，
公诗已似玉无瑕。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_71','次韵李安州纪赠二十韵','周紫芝','北宋末','衣冠数人物，
伯仲高人间。
我于鸿雁行，
畴昔奉往还。
挂名华萼集，
遂尔不复刊。
暮齿慨晼晚，
得州近荆蛮。
恨公识面迟，
又复容追攀。
高风薄云汉，
秀句横笔端。
乃知同气中，
文采真斑斑。
谁将郧城水，
换取蓬莱山。
要公抚凋氓，
天意岂等闲。
玉阶有馀地，
行归鸣佩环。
上最不待久，
唾手未苦难。
念我老已熟，
无鬓堪成班。
江头忽三月，
坐见春物残。
相逢喜倾盖，
往事论险艰。
一饮未彻席，
扁舟渡惊湍。
情钟惜易别，
易别成永叹。
可怜堂下水，
故作声潺湲。
风流倏云散，
人生岂长欢。
愿公寄尺书，
细行勿轻删。
仍烦巧匠手，
著意镌坚顽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_72','北湖暮春十首','周紫芝','北宋末','东君无意惜花残，
留得青山隔雨看。
可怪天公不怜客，
绿阴成后却春寒。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_73','北湖暮春十首','周紫芝','北宋末','北湖看雨两春馀，
忘却渔村笠泽居。
去岁莺花犹是主，
今年须鬓不胜疏。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_74','北湖暮春十首','周紫芝','北宋末','花到酴醾欲尽时，
一春已是燕游稀。
旧来持酒听歌处，
乞与东风燕子飞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_75','北湖暮春十首','周紫芝','北宋末','长安市里人如海，
静寄庵中日似年。
梦断午窗花影转，
小炉犹有睡时烟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_76','北湖暮春十首','周紫芝','北宋末','几日春风自在颠，
谁家相唤上鞦韆。
难留花住那堪雨，
不奈天寒更禁烟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_77','北湖暮春十首','周紫芝','北宋末','洛红闻说烂如霞，
应著青油密护遮。
莫剪姚黄供老眼，
使君头白懒看花。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_78','北湖暮春十首','周紫芝','北宋末','韦郎诗淡少人传，
贪看仙书不爱眠。
闲磨小团新样月，
拨灰重试古龙涎。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_79','北湖暮春十首','周紫芝','北宋末','西施乳白鱼供箸，
樊素唇红果荐新。
不恨江干春晼晚，
旅庖犹是慰愁人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_80','北湖暮春十首','周紫芝','北宋末','落絮天慵草渐匀，
最迟红药又成尘。
苦无黄鸟能歌舞，
连日春阴闷杀人。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_81','北湖暮春十首','周紫芝','北宋末','燕梁夫妇几时归，
养得新雏总解飞。
投老卜巢犹未定，
可怜人不似乌衣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_82','次韵元相题到花亭','周紫芝','北宋末','从他白发三千丈，
莫管人生七十稀。
满载月明歌一曲，
到花亭里醉中归。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_83','送李瑞昌','周紫芝','北宋末','庐阜老人心古锥，
颇学子长多爱奇。
晚生恨不见前辈，
一谈往事神先驰。
龙眠人品似摩诘，
不比老阎呼画师。
往时袖手阅神骏，
三马就毙何由追。
都人一日传万口，
后生闻此心怀疑。
诸孙今喜典型在，
此事颇从君得之。
吾皇仁圣重贤士，
子孙必录初无遗。
但令苛政不如虎，
会有善事令天知。
碧油拥被报政急，
桁杨卧壁催科迟。
他年父老歌遗爱，
为君摩石题苍碑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_84','余手植木芙蕖数十本山亭之下比闻颇为群羊践履','周紫芝','北宋末','春去无花伴白颠，
旋栽红艳照霜前。
髯郎莫剪柔柯去，
留作秋风一醉眠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_85','送高仲思提干','周紫芝','北宋末','狝猴莫厌土牛迟，
天马能行老更奇。
论事颇遭官长怒，
洁身惟恐世人知。
簿书奔走聊应尔，
台阁飞腾自有时。
云落断鸿谁是伴，
尺书何日慰相思。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_86','送莹老住灌溪','周紫芝','北宋末','一年身寄水南村，
谁把禅床一席分。
去住随缘本无意，
道人踪迹似孤云。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_87','送莹老住灌溪','周紫芝','北宋末','竹坡无物可关怀，
只有青山眼为开。
未识灌溪真面目，
烦君著句画将来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_88','送杨师醇之临安兼呈师古','周紫芝','北宋末','家在湓城五老山，
与君相望各江干。
如何肯拨艅艎棹，
便欲来同苜蓿盘。
倾盖尽知今日意，
买邻仍结旧时欢。
菊觞浇酒无离恨，
淡榜书名看二难。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_89','拟省题桂林一枝诗','周紫芝','北宋末','晋祚传千载，
贤科重一时。
拟横金殿栋，
先剪桂林枝。
月窟根盘壮，
烟岩雨露滋。
孤芳宁有种，
凡木自多姿。
臃肿樗空大，
风流柳漫垂。
惟应太邱令，
功德季方知。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_8_90','秋来久不作诗书所感','周紫芝','北宋末','雨蹙江涛壮，
天含暮霭低。
年华添老色，
风物似年时。
富贵浑无念，
情怀不到诗。
度秋无一语，
已是俗人为。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_91','寄李安州未得别后书二首','周紫芝','北宋末','未得安州信，
空添楚水秋。
雁寒飞不到，
江远望难休。
去国双红旆，
携家两白头。
可能无一字，
分慰老人愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_92','寄李安州未得别后书二首','周紫芝','北宋末','鄂渚他时县，
江南尽处州。
平生求识面，
此地忽同游。
湖外公开府，
江边我上楼。
尺书何日到，
能寄近诗不。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_93','送富川秋举五君子','周紫芝','北宋末','云衢欲上马蹄轻，
莫问长安路几程。
双剑竟须腾巨泽，
夜光元自当连城。
偶因劝驾江边日，
犹记胪传玉陛声。
澹墨榜知何日出，
拟开春瓮为君倾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_94','收小儿刊书二诗因趣其归','周紫芝','北宋末','黄梅雨熟汝辞家，
数得秋风到藕花。
书里悬知有归日，
醉中不复问年华。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_95','收小儿刊书二诗因趣其归','周紫芝','北宋末','庐峰今已卜菟裘，
心共长江日月流。
莫待西风彫绿草，
速来随我上归舟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_96','次韵强幼安中大以仆筑室濂溪见寄','周紫芝','北宋末','归去来兮复几时，
临流屡欲唤篙师。
种粳有地供饥腹，
佩犊无人作去思。
偶著衣冠真是梦，
倦寻丘壑已嫌迟。
如今真在庐山里，
二妙堂成更乞诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_97','强幼安中大示乐闻过斋记以诗为谢','周紫芝','北宋末','白璧摩挲未有疵，
榜斋铭座尚防微。
欲从今日求闻过，
故说当年是昨非。
言行固知无里襮，
吏民何处不恩威。
欲参函丈师全德，
此去应须便拂衣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_98','题赵倅家獐猿图','周紫芝','北宋末','易生画手妙，
幻出猿与獐。
双猿挂树枝，
二獐回目光。
乌衣白面两臂长，
雌雄相逐争跳梁。
秋山果熟腹自饱，
云蹬路绝人谁伤。
下临长啸颇自得，
那愁解舞绯衣郎。
二獐惊怪久眦睨，
深羡两猿高据烟林藏。
猿狙喜怒不足说，
獐鹿町畦宁无场。
枝高地卑能有几，
蚿蛇自可俱相忘。
富贵贫贱各有适，
也恐万事谁能量。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_99','雪中同上醉山','周紫芝','北宋末','驾言陟前冈，
胜赏追良辰。
苍黄惨暮色，
浩荡飞瑶尘。
冰花似有意，
娱我坐上宾。
但恐白模糊，
偶失青嶙峋。
造物有奇事，
变灭无逡巡。
斜阳忽到眼，
万叠罗苍岷。
戏从壶中天，
漏此色界痕。
况乃文字饮，
尽属我辈人。
老守颇自愧，
缪许参冠巾。
念我千里行，
维舟在江滨。
雪既不可留，
迹亦恐遂陈。
置之勿复道，
且饮樽中醇。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_100','送章使君守竟陵','周紫芝','北宋末','长江尽此是吾州，
君去长江更尽头。
短棹只添行客恨，
清樽肯为故人留。
饱听梦泽洲前雨，
却望苍龙阙角楼。
试问尺书何日到，
会须红蓼白蘋洲。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_101','金山贯道人跨水作亭余为名以枕流亭成而仆欲去作二诗因以留别','周紫芝','北宋末','闻说朱栏照眼新，
一溪清浅共谁分。
可怜桥下无情水，
不遣龟鱼识使君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_102','金山贯道人跨水作亭余为名以枕流亭成而仆欲去作二诗因以留别','周紫芝','北宋末','与师同是一山云，
吹落江西却再分。
聚散人生俱似梦，
虎溪重过不烦君。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_103','食橄榄记客语','周紫芝','北宋末','朔风吹元云，
欲雪愁江天。
烟帆驾海舶，
橄榄来闽川。
客言似有理，
得失亦小偏。
红盐落青子，
嚼玉宜芳鲜。
色香苦未发，
遂杂春客煎。
清香虽覆碗，
翠润殊嫣然。
香味元自若，
人生浪求全。
方言田家翁，
好恶能两捐。
一食辄苦口，
弃掷古道边。
回甘入齿颊，
拾遗止流涎。
朴质固可笑，
任真亦良贤。
向来纷纷者，
妄论诚可怜。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_104','次韵桂嘉任郎中赠别二十四韵','周紫芝','北宋末','是身本蘧庐，
误得两朱轓。
朅来卧江楼，
白鸥看飞翻。
惊鸿卷西风，
吹落云水间。
江山相表里，
宇宙殊恢宽。
但苦千种愁，
不供万叠山。
幸兹洪崖君，
仙驭超人寰。
一身聊复尔，
万事不可干。
富贵倘无求，
藜藿亦自安。
不须金鼎炉，
养此玉栋颜。
纷纷一回睇，
往往俱冥顽。
有如盗蹠手，
可鲙朝饭肝。
居之彼不疑，
念念我心寒。
公今梨枣成，
心地无险艰。
横湖仅一苇，
经月无寒暄。
昔为吏曹郎，
今带儒生酸。
缪从周旋间，
获奉澹泊欢。
公已闻大道，
我犹缚枯禅。
谁知数日恶，
忽有千里叹。
古道催行辀，
满山霜叶丹。
仙凡自此隔，
无复相追攀。
馀生几何时，
白日飞惊湍。
愿公追松乔，
驾鹤骖翔鸾。
我亦上五老，
举首云间看。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_105','题卷雪楼','周紫芝','北宋末','三国英雄气似云，
江南只数故将军。
借令马上身犹健，
应笑中原鼎尚分。
谥册屡沾新雨露，
断碑空说旧功勋。
斜阳万里明如雪，
独倚栏干酒半醺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_106','大冶山中有东方寺世传东方曼倩尝读书于此寺后有圣泉凡邑人之乞子于此者随愿辄得僧慧满住持十载无日不醉癸酉冬十二月之吉趺坐示寂九日而色不变人皆携酒来酌师至暮必赪颊泚颡状如醉人然其事甚怪金山贯道人将赴东方之请于其行也戏作三诗送之因纪其事使刻之山中以传好事者','周紫芝','北宋末','先生自以滑稽雄，
何事偷身入汉宫。
跨鹤乘鸾本无定，
安知不到此山中。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_107','大冶山中有东方寺世传东方曼倩尝读书于此寺后有圣泉凡邑人之乞子于此者随愿辄得僧慧满住持十载无日不醉癸酉冬十二月之吉趺坐示寂九日而色不变人皆携酒来酌师至暮必赪颊泚颡状如醉人然其事甚怪金山贯道人将赴东方之请于其行也戏作三诗送之因纪其事使刻之山中以传好事者','周紫芝','北宋末','平生著酒满葫芦，
醉上禅床不用扶。
更把酡颜惊世俗，
方知肉眼是凡夫。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_108','大冶山中有东方寺世传东方曼倩尝读书于此寺后有圣泉凡邑人之乞子于此者随愿辄得僧慧满住持十载无日不醉癸酉冬十二月之吉趺坐示寂九日而色不变人皆携酒来酌师至暮必赪颊泚颡状如醉人然其事甚怪金山贯道人将赴东方之请于其行也戏作三诗送之因纪其事使刻之山中以传好事者','周紫芝','北宋末','谁谓灵泉易感通，
解令少妇却愁容。
道人应为众生说，
此事如何著得侬。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_109','游香岩一小室甚温洁坐客皆言雅宜听雪各赋一首','周紫芝','北宋末','鹊尾烟横不卷帘，
莫嫌好客坐无毡。
道人此室知何用，
留与衰翁听雪眠。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_110','晓发永城','周紫芝','北宋末','跨鞍不作永城留，
马上烟销霁色浮。
便恐匡庐来入望，
此行今日是江洲。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_111','瑞昌道中梅','周紫芝','北宋末','我昔西来野梅发，
今岁梅花似前腊。
流年别我谁肯留，
衰鬓羞花不成折。
昔非今是未必然，
尺短寸长何足说。
到家净洗客衣尘，
犹有匡庐半山雪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_112','时宰生日乐章七首','周紫芝','北宋末','亳后出，
莘野兴。
一德懋，
三台明。
岁在午，
月嘉平。
鼓坎坎，
玉箫鸣。
醉厌厌，
椒醑馨。
阅万古，
所未闻。
肖说像，
传尧文。
盘诰出，
德爵尊。
依日月，
庆风云。
等箕翼，
奉羲轩。
愿公寿兮锡公龄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_113','时宰生日乐章七首','周紫芝','北宋末','六亲和，
孝慈不出。
国道昌，
忠臣不立。
韪公节，
秋霜栗。
繄公忠，
贯白日。
河洛腥，
黄雾塞。
枭獍鸣，
群奸集。
靡它而从中不沐，
忠臣饮气义士戢，
主左与左公不屈。
茫茫沙漠万里天，
渺渺归船海中楫。
公之归，
天为悦。
愿寿公兮报公节。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_114','时宰生日乐章七首','周紫芝','北宋末','岁在昔，
时否屯。
河阳狩，
沧海浑。
将惰骄，
霸棘分。
盗连行，
兵蜂屯。
公决策，
摭雾雰。
丰豕封，
群羊奔。
佩橐鞬，
朝帝阍。
奸气詟，
圣道尊。
三阶明，
万室欢。
帝籍功，
永不刊。
愿寿公兮公永安。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_115','时宰生日乐章七首','周紫芝','北宋末','单于朝，
流沙暨。
天降康，
神乐只。
坐法宫，
圣天子。
稽唐虞，
制六艺。
属大儒，
明古义。
金支张，
玉帛制。
告太平，
备昭事。
天马徕，
渥洼至。
朱鸟徕，
翔九陛。
愿寿公兮报公治。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_116','时宰生日乐章七首','周紫芝','北宋末','马牛归，
文轨同。
洛邑宅，
神邱蒙。
神光流，
爟火通。
君车驾，
款郊宫。
君车回，
霈泽丰。
神既娱，
景冲融。
俗阜康，
君乐雍。
愿寿公兮报公功。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_117','时宰生日乐章七首','周紫芝','北宋末','排天门，
罗万戟。
升三陔，
祠泰一。
旗幡幡，
鼓吸吸。
降赤霄，
下瑶席。
泰一徕，
景贶集。
岁三登，
连八极。
五臣相，
宇宙一。
神降临，
罔不吉。
神言归，
恍兮惚。
愿寿公兮报公德。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_118','时宰生日乐章七首','周紫芝','北宋末','榆关以北，
一骑不驰。
孰窥汉月，
燧息烽夷。
塞草春荣，
夷氓负犁。
九州万井，
风恬俗怡。
血属相保，
母父子妻。
既续厥嗣，
亦活黄莱，
几亿万年。
维德所施，
礽云来睇。
天之报之，
寿之福之。
劫尘可数，
此报何期。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_8_119','登元次山新祠','周紫芝','北宋末','人物推前辈，
风流自一时。
空怜瀼溪水，
还绕漫郎祠。
君已新华屋，
吾犹续断碑。
谁当知此意，
只有少陵诗。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_120','过刘道士庵壁间见梁竑父苏季文诗因用其韵','周紫芝','北宋末','高卧何由雨垫巾，
关门聊此寄闲身。
长生自是君家事，
白发应怜我辈人。
多酿醉乡千日酒，
岂知浮世十朱轮。
重来却践山中约，
犹有桃花一半春。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_121','迁居二首','周紫芝','北宋末','久作怀乡梦，
今年拚不归。
奉亲犹得粟，
见客已忘衣。
凭几看帆过，
开门任燕飞。
皇天怜老病，
留此著柴扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_122','迁居二首','周紫芝','北宋末','扶病翻书卷，
移家枕断城。
云空千嶂晓，
门静一江横。
叶密催春事，
花飞恼客情。
暮霞将霁色，
招我作山行。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_123','伤春二首拟近体','周紫芝','北宋末','越罗初欲替茸裘，
二月轻寒比麦秋。
潘老凋疏空惜鬓，
庾郎憔悴不禁愁。
催归燕子春何限，
落尽桃花雨未休。
谁遣少年随梦去，
不教人似柳风流。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_124','伤春二首拟近体','周紫芝','北宋末','一幅轻纱老秃翁，
半帘疏雨著东风。
长条柳伴短条舞，
深色桃欺浅色红。
愁思但知嫌酒薄，
客情终不似春浓。
尽将黑海无名障，
付与邯郸一梦中。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_125','再赋伤春二首','周紫芝','北宋末','岂料馀生两鬓皤，
庐峰犹得共婆娑。
昔年自作南柯梦，
此去心如古井波。
官冷故人书不到，
日长斋阁睡还多。
文园曾病犹堪酒，
传语风光奈我何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_126','再赋伤春二首','周紫芝','北宋末','浔阳江上听琵琶，
买得江天且寄家。
带雨冲泥看燕子，
随风著地数飞花。
人来裹饭何妨病，
客去张罗亦自嘉。
还了世间无限债，
却修香火足生涯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_127','客自富川来言湖水已到万坡','周紫芝','北宋末','昔年唤客饮湖边，
犹记湖天五月寒。
白鹭翻空归杳霭，
惊涛卷雪到杯盘。
鲲鹏水击三千里，
云梦胸吞八九宽。
想得拍堤春涨满，
又吹飞雨湿阑干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_128','寄章复州','周紫芝','北宋末','春来未得复州书，
流落他乡我独居。
今日离群天际雁，
昔年同队水中鱼。
遥知卖剑方成俗，
想得追锋便赐车。
拟约琵琶亭下月，
伴君一醉复何如。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_129','南窗植竹数百竿后数日蔚然俱青客问种竹法作四言以告之','周紫芝','北宋末','平生寡友，
形影相吊。
与君结交，
相视一笑。
四方万里，
动静险夷。
我惟子求，
子必我随。
聿来湓江，
屋庐既正。
相子攸居，
我室乃定。
得子之宫，
于窗之南。
风茎雨叶，
蔚其鬖鬖。
人言死猫，
可引活竹。
猫死地虚，
根行竹绿。
又言无法，
移必行迷。
仍标其根，
以识东西。
区区百设，
何乃多事。
事在眉睫，
初无妙理。
穴地成坎，
碎土加筛。
沃以斗水，
和之成泥。
置竹其中，
实之以土。
土燥润久，
可月不雨。
逮其雨来，
竹既已成。
热不受暑，
寒不变青。
嗟哉此君，
以节自负。
如遇君子，
理宜调护。
君欲何法，
无法可传。
并以告子，
俾知竹贤。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_8_130','九江初识水仙二首','周紫芝','北宋末','七十诗翁鬓已华，
平生未识水仙花。
如今始信黄香错，
刚道山矾是一家。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_131','九江初识水仙二首','周紫芝','北宋末','天香不染麝煤烟，
家近龙宫宝藏边。
世上铅华无一点，
分明真是水中仙。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_132','新作布裘二绝','周紫芝','北宋末','青裘短袂瘦躯长，
拄杖横担古锦囊。
变尽形容人不识，
家僮应怪贺知章。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_133','新作布裘二绝','周紫芝','北宋末','少日无心佩紫囊，
一生裘葛是衣裳。
但知野服寻山便，
不学唐装又晋装。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_134','吴传朋郎中自出新意作游丝书妙绝一时士大夫皆赋诗为作数语书轴尾','周紫芝','北宋末','公孙舞浑脱，
长史妙心画。
老兵涂帚垩，
中郎出飞帛。
得法自所见，
岂用规畴昔。
随人作书奴，
终与古人隔。
游丝最无事，
何止但百尺。
飞来若有态，
吹去忽无迹。
使君看青天，
意外得新格。
映空疑有无，
著纸互络绎。
神机殆天授，
至技非人积。
遂令一丝轻，
可挂千金石。
聊将画沙锥，
幻出虫网壁。
我虽不解书，
好书乃成癖。
公如傥有意，
能事不敢迫。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_135','传朋为作游丝小轴报以长句','周紫芝','北宋末','竟陵老守尚书郎，
平生墨妙窥钟王。
会令夜鬼助奇崛，
更与游丝争短长。
游丝忽从天际落，
洗眼熟视无毫芒。
痴儿著意吹不起，
春风无力难飞扬。
草虽号圣亦可到，
此品入神谁复强。
使君怜我颇知好，
五十六珠投夜光。
溪藤捣纸滑胜玉，
古锦缝囊牢秘藏。
要遣张颠与醉素，
不敢与公分雁行。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_136','读司马长卿传','周紫芝','北宋末','扬雄新著草元书，
却笑相如赋子虚。
借使曲终方奏雅，
比君符命复何如。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_137','病起节物可惊效柳子厚','周紫芝','北宋末','病起忽数日，
杖策周吾庐。
桃花手新栽，
小红今欲舒。
萱草未出土，
苗叶将扶疏。
物变乃如此，
光景难踟蹰。
退自观我生，
今形复何如。
梦前黑垂髫，
梦后霜入须。
安得万丈绳，
缚此窗间驹。
先生可笑人，
为生本田䱷。
晚污琳馆粟，
俾代南山锄。
皇恩浩如海，
臣报终难虚。
老力虽不足，
闲日幸有馀。
愿炷金鼎炉，
日诵琅函书。
跪祝望天门，
圣寿如居诸。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_138','纸帐二首','周紫芝','北宋末','雪帐垂空万事休，
醉来高枕竹猫头。
不知金谷园中障，
输与侬家几百筹。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_139','纸帐二首','周紫芝','北宋末','荆王翠羽衾中梦，
太尉销金帐里歌。
若以道人银色界，
虽无欢笑亦无魔。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_140','秦观文生日诗三十韵','周紫芝','北宋末','宝祚开苍箓，
炎精表赤符。
乾坤归圣统，
廊庙得真儒。
事借帷筹定，
颠从漏刻扶。
兵销九节度，
仪肃五单于。
意与神明会，
功知传记无。
公师隆化道，
嗣相恊神谟。
世业垂馀庆，
天心究永图。
貂冠亲日月，
玉座接都俞。
自可均调鼎，
犹谦谢秉枢。
槐庭何日见，
绣衮几时纡。
大府连甍栋，
翔鸾踵步趋。
侏离将入贺，
象寄尽交孚。
光耀三台宿，
喧腾百雉都。
传呼凤尾诺，
导从火城驱。
隔坐恩由占，
同朝礼固殊。
位虽仍亚保，
望久在中区。
艺籍明经殿，
文星照石渠。
诸生咨典故，
列辟奉规摹。
往岁方平难，
斯民稍避胡。
大臣俱宿德，
四海尽夷涂。
效已知无敌，
天应信不诬。
他年各安堵，
此日记垂弧。
云篆祈千载，
霞浆赐百壶。
中人传诏旨，
东阁拥金朱。
旧物归龙榜，
欢声彻海隅。
一门天为喜，
万里物皆苏。
寒士勤推毂，
和春入朽株。
恩尝蒙草木，
才不补唐虞。
只有祈年颂，
持为报德珠。
第惭床下拜，
云峤隔江湖。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_8_141','题陈大卿三径堂','周紫芝','北宋末','一身和影共婆娑，
看尽人间两鬓皤。
要好只销长闭户，
便开三径已为多。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_142','晓晴','周紫芝','北宋末','曈昽晓色上帘旌，
吹尽江头滴雨声。
百岁一生常苦恼，
三春几日好晴明。
从他落絮随人去，
但趁青山放脚行。
尚有诗肠新鼓吹，
满携樽酒听黄莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_143','杨得臣见和晓晴长句用韵奉酬','周紫芝','北宋末','西风猎猎转红旌，
吹尽春霖点滴声。
晓送楚云归陇去，
夜看淮烧隔江明。
舞狂恨我无长袖，
句好从君得短行。
拟为新晴歌一曲，
谁将此调付莺莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_144','杨得臣见和晓晴长句用韵奉酬','周紫芝','北宋末','诗翁老去得双旌，
惯听清涟夜雨声。
水到浔阳心独喜，
云开庐阜眼先明。
落花已是春三月，
飞盖犹堪酒数行。
寄语草元窗下客，
忍令辜负晓啼莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_145','杨得臣见和晓晴长句用韵奉酬','周紫芝','北宋末','归心何事等摇旌，
叔起能诗近有声。
岂料从游如梦寐，
不知风雨过清明。
拍浮我自堪娱老，
矍铄谁应更请行。
此去定交君见许，
为歌伐木赋鸣莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_146','杨得臣见和晓晴长句用韵奉酬','周紫芝','北宋末','上最初无善可旌，
归来和雨听江声。
自怜老眼昏花甚，
乞得晴窗夕照明。
莲叶系舟惊水满，
鱼须拄颊看云行。
君能著屐时相过，
犹有残春一雨莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_147','杨得臣见和晓晴长句用韵奉酬','周紫芝','北宋末','何处笼街引旆旌，
老翁高卧听鸡声。
看花强起寻韦曲，
谒帝空思入大明。
有兴时弹流水调，
无情懒赋丽人行。
青春别我谁为伴，
只有能歌绿树莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_148','杨得臣见和晓晴长句用韵奉酬','周紫芝','北宋末','随缘南北似风旌，
饱听波涛处处声。
今日园花风里尽，
到时江月雪中明。
虽无格磔钩辀语，
尚有媻姗勃窣行。
谁饯东君沸歌管，
琵琶弦上啭春莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_149','奉酬晁强伯见和晓晴长句','周紫芝','北宋末','元祐文华揭䌽旌，
金沙别乘有家声。
天教云彩归何处，
诗共晴光欲斗明。
已阁山前山后雨，
尚堪水北水南行。
不应文石班中客，
肯伴韦郎赋晓莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_150','奉酬晁元采三和前韵','周紫芝','北宋末','见贤殊未驻干旌，
叩户先闻剥啄声。
春去鸟啼千树暗，
雨馀花落一窗明。
新诗已得前人法，
病足惟追逸骥行。
何日长安君得意，
著鞭闲听上林莺。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_151','曹度坚待制罢帅成都归江南以川中唐人六十家诗见遗作长句为谢','周紫芝','北宋末','三月瞿塘峻江水，
万里归来蜀都帅。
尽收五十四州书，
画舸连樯当歌吹。
有唐文士几千人，
文不逮汉诗则异。
开元天宝光焰长，
长庆元和殿唐季。
化入宝奁脂泽中，
亦有风满有能事。
六十馀家三百年，
天遣遗风未全坠。
青衫昔日同舍郎，
老傍人间百无意。
将焚笔砚技辄痒，
未说风骚心复醉。
公堂许我能篇章，
遗以斯文慰憔悴。
徒令后学羞捧心，
谁与前贤共联辔。
为公隐几抱残编，
聊伴青奴问朝霁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_152','雨中读韩致光诗偶池上鹿葱盛开因效其体','周紫芝','北宋末','曲栏干外水平阶，
池上朱扉绕翠苔。
燕子飞来人不到，
鹿葱花在雨中开。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_153','雨中读韩致光诗偶池上鹿葱盛开因效其体','周紫芝','北宋末','雕尽朱颜白尽头，
种花本为欲忘忧。
谁知花上风和雨，
添得周郎一段愁。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_154','天申节日谒告不赴赞祝拟王仲初','周紫芝','北宋末','小臣拜祝奉千秋，
敕赐宫花忆满头。
今日江边揩病眼，
五云常望帝王州。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_155','天申节日谒告不赴赞祝拟王仲初','周紫芝','北宋末','吾皇一出万方春，
自合倾心祝至尊。
乞得养痾闲地禄，
此生尺寸是君恩。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_156','题画蛱蝶小扇','周紫芝','北宋末','花里飞来粉翅疏，
香罗扇上得形模。
只缘容易无人爱，
但说滕王蛱蝶图。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_157','题小扇','周紫芝','北宋末','小扇题诗墨色新，
碧纱囊剪藕丝匀。
月团常在纤纤手，
不用流苏拂暗尘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_158','池莲初著数花','周紫芝','北宋末','数枝临水见纤娥，
新采红蓝染袜罗。
传语薰风莫吹去，
且容留眼看微波。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_159','富水军治有巨泽往岁荷花满湖郡守岁取荷叶可贸百千一日曝之湖滨大风吹卷飞数十里顷刻俱尽又采叶者颇以为苦沥膏油以毒之逮仆至阅两岁无一花今年结茅于此穴小池植数十根而花已可观因感前事遂书之','周紫芝','北宋末','湖边老守湖是家，
湖光十里蒙寒沙。
我来不见花如锦，
但闻荷叶飞天涯。
小池今无十许步，
晚雨亦开三数花。
人生乐事无多少，
可意应须随分了。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_160','剪松毛小栅以诗落成','周紫芝','北宋末','东堂坐甑遭炊蒸，
西檐烈日方腾腾。
炎官张伞火渐炽，
乌豕渡河云不兴。
五官大夫有遗种，
十八公自分云仍。
羲和挥戈不可却，
郢匠剪毛归作棚。
南风飒瑟出馀韵，
怒龙奋迅苍髯升。
香来鼻观过一雨，
便恐冰麝终难胜。
天公割此一席地，
付与老翁来曲肱。
何时快著短齿屐，
信手自把南山藤。
卧听松风满山雨，
去作水边岩下僧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_161','五月二十四日晚雨忽晴浴罢独卧池亭云峰奇峭既夕方散','周紫芝','北宋末','长虹截天雨初断，
孤日翻光上银汉。
忽从海底出三山，
就中蓬莱正奇观。
黄金涂阙射日光，
白玉飞栏入天半。
青童舞女各媻姗，
手执云幢影凌乱。
想得神清洞府君，
应榜春皇侍香案。
群飞白鹤徒尔为，
化作苍狗何劳看。
神仙出没不久长，
碧落天宫岂容玩。
荆王晓梦只须臾，
神女乘鸾逐云散。
人间幻化无不尔，
空复欷歔一长叹。
老人假寐忽举头，
但见明星光有烂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_162','五月悯雨颇闻饥民弄兵于严衢两州间三十韵','周紫芝','北宋末','长天望油云，
槁黍待甘霔。
一雨有丰凶，
死生分旦暮。
颇闻两州民，
岩谷多啸聚。
有司幸眼前，
白对急追捕。
斯民如婴儿，
慈母仰调护。
岂容使之饥，
而反贻以怒。
救饥当未然，
为食须早具。
不雨三月馀，
开口久待哺。
岳牧事遨游，
傲聣曾莫顾。
遂令出偏师，
往往勤远虑。
人亦甚畏死，
阶乱岂无故。
汉有大司农，
为国最知务。
谁知部使者，
出纳反坚固。
输金买朝粮，
仅得鸟一嗉。
尚尔吝弗予，
民隐独何愬。
几何不为盗，
悔过苦无路。
富儿家多金，
封财亦良裕。
积金谋子钱，
切骨被疽蠹。
闭粜不肯售，
叩门如蚁附。
忿气生一时，
万死有不惧。
政坐守宰痴，
申令苦不素。
有时出万斛，
官为复常赋。
大或旌义闾，
小或赐朝酺。
民情非木石，
岂不遵劝谕。
岁事小不登，
彝伦坐成斁。
无良二千石，
万事成缪误。
况乃六月师，
金甲困暴露。
天道有报施，
人情均好恶。
会当明诛赏，
典刑正王度。
庶几令远氓，
因此出沈痼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_163','祁居之见过仆出未归明日作二诗为谢','周紫芝','北宋末','家近平湖草树青，
几年于此寄高情。
有时亦为衰翁出，
谁道庞公不入城。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_164','祁居之见过仆出未归明日作二诗为谢','周紫芝','北宋末','不见前贤畏后生，
一闻君语为心倾。
何时却约高轩过，
重听门人说老成。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_165','雨后极凉简竹坡四君子','周紫芝','北宋末','江城夏六月，
大旱草木黄。
稽首文殊师，
驾言天池阳。
为乞一斗水，
普救千里伤。
微云生宝髻，
法雨遍大荒。
霈为一尺霖，
化作三日凉。
老人不耐暑，
内热煎中肠。
吹以碧落风，
灌以丹露浆。
我有方丈室，
彩榜名妙香。
呼我四君子，
聊与之徜徉。
朝凭共乌几，
夜宿同方床。
永结无情欢，
此乐殊未央。
荣瘁不改观，
死生知有常。
岂不贤俗子，
与世随低昂。
翻手覆手间，
此道宁久长。
愿我四玉友，
永言不相忘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_166','七夕','周紫芝','北宋末','七夕相逢说牛女，
晋魏以来传乐府。
金冠玉帔照灵河，
不见此身闻此语。
何如当日两神仙，
空中一别五千年。
五龙驾车各异色，
万里乘云来九天。
麻姑女子十八九，
青丝作髻爪为手。
擗麟荐酒进行厨，
撒米成沙只回肘。
为言东海将扬尘，
蓬莱水浅无升斗。
蔡经得道心尚凡，
背痒自速方平鞭。
上界真仙足官府，
牛女之说真茫然。
䌽楼对月谁家倩，
更就天孙乞针线。
何不苦学麻姑仙，
养取红颜如玉烂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_167','仆所居盖濂溪先生之故基也有井清甘而寒先生尝以比谷帘今为路人所汲余尝为作亭号濂溪泉而为之铭今未暇也','周紫芝','北宋末','山下清泉古甃寒，
百年谁为发幽潜。
可怜昔日供茶鼎，
曾与先生当谷帘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_168','梦行西湖梅花下','周紫芝','北宋末','久把西湖作故乡，
至今清梦到湖傍。
分明昨夜经行处，
一色梅花十里香。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_169','梦行西湖梅花下','周紫芝','北宋末','春云收尽忽斜阳，
梦里梅花带雨香。
却上小舟谁是伴，
回头只有棹船郎。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_170','食芡有感二首','周紫芝','北宋末','鸡头子熟客新尝，
流落空嗟各异乡。
红线绿荷香里梦，
十年灯火记钱塘。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_171','食芡有感二首','周紫芝','北宋末','翻香引睡一胡床，
剥芡寻诗度日长。
若得长闲了无事，
人生如此亦何妨。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_172','书祁居之家小阁','周紫芝','北宋末','李渤筑长堤，
三千五百尺。
为我绝平湖，
遂识柴桑宅。
高人淡无营，
小室自生白。
倚壁横两床，
并坐可四客。
时闻苍蝇馆，
不厌蜗牛馘。
谁知湖尾山，
抱负萦水石。
繁阴庇芳姿，
收拾在几席。
天地本高明，
胸次有宽窄。
固应世外境，
颇与俗眼隔。
我欲为君留，
雨意良霂霢。
对眠分小窗，
夜语要剧会。
须臾携被来，
更待风雨夕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_173','次韵都倅题赵菘老竹涧听雨亭','周紫芝','北宋末','西来倦客厌飘零，
一见宗枝眼为青。
世事绝知尘外少，
雨声更在竹间听。
铿如曲奏江边瑟，
清伴风鸣塔上铃。
想得荆州都别驾，
诗成幽梦晓初醒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_174','晓雨用都倅韵','周紫芝','北宋末','乱敲檐瓦晓初零，
声入孤灯影半青。
枕上有诗因雨得，
窗间无客对床听。
翠光洗出山千叠，
金色添成菊万铃。
收取新凉归酒盏，
莫将双眼为愁醒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_175','夜雨再用都倅韵','周紫芝','北宋末','半世常愁夜雨零，
断肠无复鬓丝青。
又将船舰舟中梦，
移入梧桐叶上听。
凉吹渐欣归枕簟，
好诗那更似鸾铃。
欲知多少江湖兴，
病眼无眠彻晓醒。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_176','夜闻骤雨枕上二首','周紫芝','北宋末','星斗阑干云翳销，
黄昏犹未有微飙。
谁将枕上三更雨，
捲作钱塘八月潮。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_177','夜闻骤雨枕上二首','周紫芝','北宋末','山南未作小徘徊，
坐想奔流万壑雷。
三峡桥边风雨样，
先将此谶入诗来。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_178','季夏极暑正昼草木俱萎独吾坡上数君子玉立苍然傲睨自得岂杜少陵所谓脩竹不受暑者乎','周紫芝','北宋末','烈日当正昼，
长天无一云。
草木失颜色，
葳蕤困烧焚。
阳春始用事，
庶类争芳芬。
小草最无名，
罗生费锄耘。
凡花颇矜持，
随风弄馀薰。
一朝值炎酷，
尔辈徒纷纷。
苍苍不改操，
惟我坡上君。
脩茎粲碧玉，
茂植歌屯云。
有如独醒人，
不受曲蘖醺。
如彼至人者，
自与世俗分。
入火且不热，
况乃逢朝昕。
小人柔弱姿，
难与君子群。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_179','送吴甥归秣陵','周紫芝','北宋末','人生良苦不自知，
三折肱乃成良医。
老夫年少不知此，
请为甥也今言之。
平时颇喜诗有味，
晚乃竟坐寒无衣。
人言诗成本无用，
小技止可持自怡。
一闻斯言寝不寐，
尽欲弃去无孑遗。
人皆见之唾不顾，
汝乃掇拾归何为。
前年行都子访我，
值我偶得南州麾。
汝之老母我伯姊，
何为弃养行相随。
极知饥寒子良苦，
况乃窀穸归无期。
翁今儿孙渐满屋，
子六八女肩相差。
归囊羞涩止有此，
世事乃尔真成痴。
渭阳老将如病骥，
肉瘦到骨那能肥。
枯萁成豆不足较，
甥也幸有骅骝姿。
丈夫岂合长贫贱，
慎勿琐细含酸悲。
天寒霜劲路如掌，
矫首一望秋风嘶。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_180','小儿刊归自宛陵喜甚成诗三十韵','周紫芝','北宋末','吾家自曾高，
善积岂一日。
尔祖工辞章，
论议抱经术。
我亦学弓冶，
少小弄文笔。
汝兄今有儿，
束发行授室。
义方稍加训，
书种恐未失。
汝亦千里驹，
似有趻踔质。
顷为国子弟，
两战一败黜。
犹复胜端舒，
不识六与七。
胡为久别离，
嘉月六换律。
去时春气温，
飞燕如点漆。
只今秋风高，
露草鸣蟋蟀。
老眼望千里，
怀抱难尽述。
有时坐如痴，
经月发不栉。
酒酸或忘饮，
客至亦懒出。
汝书江南来，
归计似可必。
翁也望汝怀，
疑有后皇橘。
奴婢喜欲颠，
精糳治黍秫。
辛勤酿斗酒，
待汝解忧慄。
访旧说乡闾，
呼儿共梨栗。
念汝童稚时，
顷刻不去膝。
况今待汝来，
时序恐凛凓。
竹舆听咿哑，
云岭走崒嵂。
吾无千金产，
遗汝使汝逸。
惟有骪骳文，
待汝成卷帙。
二事倘可了，
馀亦遑暇恤。
是时新堂成，
小室颇温密。
夜席照寒灯，
红炉共呫哔。
皇天既休老，
谢事即移疾。
汝当著归鞭，
快马追健驿。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_181','次韵郭元寿泊舟琵琶亭下夜闻吹箫','周紫芝','北宋末','舟在琵琶旧日亭，
玉箫更弄月微明。
湓江故事新歌曲，
便是香山此夜情。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_182','次韵元寿见赠','周紫芝','北宋末','画檐横著小阑干，
看尽西来最好山。
带雨楚江依约处，
隔烟淮树有无间。
已烦造物分幽趣，
合就馀年了燕闲。
借使眼前无此妙，
可能不似鸟知还。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_183','送元寿归华亭','周紫芝','北宋末','念昔得左鱼，
相逢各萍梗。
我方事米盐，
君亦厌簿领。
岂曰吾无徒，
其实但吊影。
殷勤共杯酌，
邂逅得俄顷。
坐中老于菟，
神色甚凶犷。
一躯垂豕腹，
两眼张牛猛。
酒行殊未阑，
幽事颇遭梗。
人生聚散多，
快意复难逞。
只今几何时，
我居已深屏。
君亦乘归舟，
久别劳问省。
长言出新诗，
小酌共昼永。
平生发硎刃，
妙割无肯綮。
岂容金九傍，
卧著函牛鼎。
庙堂重汲引，
尽取无短绠。
会当从隗始，
岂复杂哙等。
愿君飞尺书，
早发慰晚景。
功名要激昂，
人事勿暖冷。
为我谢黄郎，
无路勤造请。
熟醉倘有味，
高卧不须醒。
仍烦织筠笯，
丹砂寄圆顶。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_184','都倅寿诗二首','周紫芝','北宋末','读尽人间未见书，
几曾回眼到园蔬。
文章笔下飞云锦，
今古胸中著石渠。
万事要询胡伯始，
九重应问马相如。
明年我欲为公寿，
想得追锋已赐车。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_185','都倅寿诗二首','周紫芝','北宋末','文石班中侍从联，
如公真合在甘泉。
何由魏阙催归诏，
未到荆州去路边。
分外寡求应是福，
静中有寿不须仙。
满斟玉色长生酒，
烂醉庐峰五老前。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_186','晚眺','周紫芝','北宋末','望极应千里，
人家自一村。
客帆何处落，
邻碓隔烟闻。
山自秋来瘦，
江从雨后浑。
平生幽独意，
为客却销魂。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_187','九江木犀甚富而香亦奇绝江东所无也','周紫芝','北宋末','自从春去忆疏梅，
直到秋来数木犀。
不隔幽香微雨细，
偏宜小树夕阳低。
无诗可说难言态，
有酒应须著意携。
家在东江苦无此，
莫嫌为客在江西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_188','再赋木犀','周紫芝','北宋末','新诗几欲赋幽姿，
才浅真惭秃角犀。
未可便教金粟尽，
直须看到玉蟾低。
风吹香去天谁管，
花趁人来我自携。
不对此郎时一醉，
空令墓上揭征西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_189','再赋木犀','周紫芝','北宋末','寻香剪得耐寒枝，
不羡腰围宝带犀。
塘桂自应同臭味，
岩花未可较高低。
秋风易老空成恨，
佳客无人莫漫携。
挽取芳条供燕坐，
绝胜骑马号安西。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_190','谢祁居之惠桃竹杖','周紫芝','北宋末','老翁年少白如玉，
初学裹头双鬓绿。
一心走觅梨与栗，
两脚登山健如鹿。
中年脚力惊早衰，
腾踔安得如儿时。
挟弓持满走避贼，
尚与箭锋争疾迟。
如今老矣那忍说，
七十上身头似雪。
年来脚力何所似，
钝如罢牛跛如鳖。
先生强欲相扶持，
赠我江心桃竹枝。
竹夫人痴不解语，
木上座肯行相随。
况乃柴焰如削铁，
四十九层排玉节。
天公与我山作堂，
木落霜空秋九月。
与君共看南山云，
安可一日无此君。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_191','十月十七日大风约客登虎渡亭观浪人言今日下水风不可往也戏作此篇','周紫芝','北宋末','长江水自光摇空，
阳侯欲与风争雄。
涛头不受水犀弩，
鲸波欲卷冯夷宫。
径须便入虎溪口，
净洗平吞云梦胸。
人言上水得风浪，
下水得风终少功。
平生万事尽难偶，
政要东风渠不东。
江边一叹良细事，
而亦龃龉烦天公。
儿时望事到白首，
事不如意十八九。
不如快饮风流泉，
夜看青山衔北斗。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_192','送杨师醇赴竟陵法官','周紫芝','北宋末','平昔交游未易论，
世间谁复似君真。
五花判事元无意，
三尺从官政为贫。
酒贱颇宜呼客饮，
诗成莫忘寄书频。
使君若向新堂老，
今是开山第一人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_193','次韵杨师古留别','周紫芝','北宋末','寄食客乡远，
谁人肯见过。
江山来往数，
兰玉弟兄多。
可恨浇愁酒，
能摧转棹波。
几时书到眼，
此别意如何。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_194','晚思','周紫芝','北宋末','滩沙露尾江水乾，
江洪束峡江流湍。
千山落木风转急，
万里飞鸿天更寒。
暮云政拥苍玉玦，
落日忽下丹砂盘。
他乡久客去未得，
悠然东望心悲酸。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_195','二妙堂望九十九峰雪','周紫芝','北宋末','北风卷地天漫漫，
长空下舞十翔鸾。
天公吹絮作飞雪，
大匠琢玉成群山。
群山南来西北折，
走如连环断如玦。
接天朝同一色云，
映水夜伴中宵月。
谁知三千大千界，
有此九十九峰雪。
人间未见固难名，
天上有之那可说。
老夫才尽晚益缪，
笔力应无此雄杰。
徐熙著色岂可画，
大年小景不足悦。
谁当貌此一段奇，
留与高堂洗炎热。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_196','雪后步至江亭','周紫芝','北宋末','老人携家无窟穴，
晚得一邱藏曲折。
今朝日出天色佳，
拄杖来看山顶雪。
青山叠叠几十峰，
桃竹班班三百节。
山晴颜色看转好，
老健脚力殊未竭。
出门暮色尚馀霞，
步到江亭已生月。
归来附火却关门，
茶熟诗成意良悦。
客有劝我勿作诗，
奈此江山两奇绝。
扪须仰面看屋梁，
心自知之口无说。
天将此段付诗人，
世间那有闲风月。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_197','时宰生日诗五首','周紫芝','北宋末','皇天产万汇，
琐碎不足名。
青黄百草中，
幻作芝九茎。
恶鸟不敢语，
紫凤丹霄鸣。
尤物倘或出，
四海称隆平。
太史上图牒，
后夔奏韺䪫。
岂知人中瑞，
千载乃一生。
神高下苍箓，
昴宿扶汉氓。
天亦甚爱惜，
殷勤遗黎茕。
圣主答天意，
一酌尊老成。
愿公于斯年，
拥佩朝玉京。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_198','时宰生日诗五首','周紫芝','北宋末','历世由羲轩，
百相标简牍。
操术难具论，
大抵一言足。
所尚必仁恩，
所禁在杀戮。
皋陶期无刑，
四海自肃穆。
敷德益所赞，
坐使有苗服。
西都郅支功，
萧相不肯录。
有唐未开边，
宋璟乃当轴。
向来多谬悠，
纷纷空食肉。
一言俞玉音，
万灶休野宿。
不战乃为功，
休兵岂无福。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_199','时宰生日诗五首','周紫芝','北宋末','维国有六职，
论道先三公。
巍峨独姬旦，
焜耀传无穷。
子房号贤杰，
妙算无遗踪。
谓可为帝师，
授书圯上翁。
周公迓太平，
道与时适隆。
张侯策虽奇，
未解销兵戎。
太师回狂澜，
仅在谈笑中。
德业与智谋，
谁能与公同。
畴人亦何知，
但说前无功。
谁知公一德，
自与天潜通。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_200','时宰生日诗五首','周紫芝','北宋末','种木当培根，
疏流必深源。
尝闻活万夫，
报在子与孙。
只今父子懿，
同拱羲皇尊。
文方班马富，
业与皋夔伦。
奕奕两貂蝉，
煌煌一朱门。
圣道家所传，
兰树俱有闻。
韦氏守一经，
事业不足论。
金张誇富贵，
盛德无遗芬。
父师固难量，
有功在元元。
为公祝遐寿，
千载同风云。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_201','时宰生日诗五首','周紫芝','北宋末','鲁人用真儒，
齐田归郓欢。
当时号圣相，
晏语甚眧焕。
往者遭承平，
燕安嗟久玩。
三纲既已解，
四海兵几半。
天戈不忍挥，
胡骑忽云散。
功高陋古今，
事易止朝旦。
方知今相圣，
难复与鲁辨。
世罕班马流，
无言可称赞。
愿公守成勋，
宝历庆千万。
芜词不足录，
至意良可献。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_202','客有以仆托病谢客者甲戌除夜作','周紫芝','北宋末','梦中七十四番春，
谢客明年懒见人。
已是天公怜我老，
苦无官长怕谁嗔。
腊随残漏声俱尽，
鬓共疏梅色斗新。
招取云山来一笑，
竹坡犹有此闲身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_203','祁居之作亭山间名之以宜谓四时之皆宜也其后寓安有亭未名居之使榜以似宜寓安虽从之而其诗乃有未必输公之语气似未平也寓安欲余赋诗因为解纷且以见二公相忘之意','周紫芝','北宋末','先生有亭宜四时，
乃使寓安名似宜。
寓安口诺心未肯，
更欲老翁聊决疑。
老翁百事尽称好，
一生和罗常作椎。
况是宜亭颇静秀，
闻说似宜尤复奇。
两山相望俱不恶，
二老较胜知何为。
会当扶病蹑双屐，
携酒君家为君醉。
不知春事已过眼，
但见此亭俱可意。
且对青山食蛤蜊，
一笑谁能知许事。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_204','晚霁效韦苏州','周紫芝','北宋末','重雾翳晓日，
相持决阴晴。
须臾忽战胜，
日杲中天明。
积雪压竹腰，
欲举如垂旌。
冰凌既融液，
意气还峥嵘。
花木手新植，
未可分死生。
庶几僵仆根，
可与微阳争。
况乃田亩间，
春事亦渐营。
新绿染麰麦，
馀甘归竹萌。
饱食遂可料，
聊助春山行。
一晴亦细可，
系我忧喜情。
我诗不浪作，
有诗君勿轻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_205','寄题章汉直中虚堂','周紫芝','北宋末','谷以虚而应，
乐以虚而出。
妇姑时勃蹊，
作室坐自窒。
天地犹橐籥，
用固不能屈。
学而不见道，
方寸等暗室。
谁知道集虚，
通一万事毕。
推此以游世，
于道乃其一。
异哉子章子，
妙悟造理窟。
何止学美身，
虚静了不汩。
愿君师心斋，
守此能勿失。
室以虚生白，
水以止鉴物。
此意似太漫，
未免遭骂诎。
我亦取斯言，
聊用自湔拂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_206','徽宗皇帝挽词二首','周紫芝','北宋末','治格兴王日，
功垂定鼎年。
重新周制度，
尽有汉山川。
宝墨星辰烂，
皇猷典诰传。
小臣回老眼，
垂泣望云天。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_207','徽宗皇帝挽词二首','周紫芝','北宋末','主器归储嗣，
神尧意独高。
帝方游赤水，
人已抱乌号。
万国瞻双阙，
三山戴巨鳌。
思陵风雨夜，
松柏漫萧骚。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_208','吴师鲁挽词','周紫芝','北宋末','少日词华豹一斑，
暮年白发老青山。
谁知笔下三都赋，
不及人间五两纶。
麟阁未输前日恨，
鹿门长享百年安。
他时隐逸书佳传，
名在宗元季孟间。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_209','王夫人挽词','周紫芝','北宋末','藁砧高义赫穷阎，
内子宜家恊凤占。
茶乳未容收净供，
蛛丝早已上香奁。
坐中有客思分髻，
林下无人解拟盐。
他日诸郎尽台阁，
会刊佳传贲幽潜。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_210','徐夫人挽词','周紫芝','北宋末','蚤岁孀居妇职修，
凛然霜桧与争秋。
木兰女解听金柝，
共伯妻能赋柏舟。
鸾诰一封身未享，
木奴千树子先侯。
可怜黄壤埋琼玉，
十里虞歌满路愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_211','郝至之挽词','周紫芝','北宋末','不见平生郝骪山，
满襟青泪只潸然。
少时插架空千轴，
老去看囊止一钱。
挈榼暗思携酒处，
跨驴谁画作诗肩。
当时刻鹄终成鹜，
唾面应须使自乾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_212','哭刘元素','周紫芝','北宋末','前度刘郎迹已尘，
交亲零落倍伤神。
桃花句好人何在，
忍看风摇燕麦春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_213','哭刘元素','周紫芝','北宋末','日饮无何自醉醒，
平生种种是真诚。
不须私作门人谥，
君亦从来苦畏名。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_214','哭刘元素','周紫芝','北宋末','中郎已老元无子，
灵运为僧只在家。
斗酒只鸡吾欲哭，
不知谁为作侯芭。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_215','刘元亢挽词','周紫芝','北宋末','交游半作白头新，
不见刘郎谁与亲。
东野命穷官止尉，
少陵才健笔如神。
皇天可是无公道，
举世何由有若人。
醉里广文渠不识，
可怜官长错相嗔。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_216','悼友篇','周紫芝','北宋末','建炎三年冬，
胡骑方南驱。
王师一败绩，
列戍如惊乌。
贼将招叛亡，
操戈横道隅。
坐令江乡地，
化作盗贼区。
平生金兰友，
之子真吾徒。
避地出三物，
夷险两不渝。
岂谓仓惶间，
遂有生死殊。
始时群盗来，
未识安所趋。
但闻戛金革，
门外争喧呼。
扪萝得微径，
密雪方纷敷。
子时索我急，
出门冲贼涂。
迟子久不至，
得报日已晡。
夫妇俱见执，
担簦入军俘。
累累五儿女，
饮泣声呱呱。
小雏从物故，
踉跄走大雏。
长女留军中，
继释二小姝。
藉草已信宿，
脱死许可图。
贼意欲解缚，
小试聊踌躇。
时方羽书至，
招谕陈嘉谟。
渠奸立授辞，
抗论苦未俞。
命子使草檄，
操笔徒嗟吁。
谓言不事贼，
高目扪髯须。
丈夫贱苟活，
请就斧钺诛。
袒裼蒙殊死，
肥白惊瓠壶。
其妻始就擒，
抱子俱沉濡。
牵挽负残息，
冻凌生罗襦。
时方燎湿薪，
四座围诸孤。
可怜玉雪姿，
不受蛇豕污。
须臾有健卒，
提刀血模糊。
声言杀藁砧，
忧愤搅郁纡。
抚掌发浩叹，
陨越不复苏。
夫义妇亦烈，
此事知久无。
自古肉食者，
未必非奸谀。
生无骨鲠资，
含死馀金珠。
石麟高嵯峨，
丰碑树龟趺。
生无征战功，
祁连巧规摹。
谁知草棘中，
高义属竖儒。
蔡琰既两聘，
生子留单于。
晚岁遭阿暪，
爱惜存微躯。
蔚宗作佳传，
浪与烈女俱。
世无采诗官，
盛事恐湮芜。
子死不足惜，
会当逢董狐。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_217','詹伯尹挽词二首','周紫芝','北宋末','詹郎胸次有奇兵，
几为楼兰欲请缨。
四海眼高空燕雀，
百年身老困鲵鲸。
跕鸢不用伤遗恨，
苍狗何尝有定名。
勋业转头浑似梦，
却将五字作长城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_218','詹伯尹挽词二首','周紫芝','北宋末','平生危论剧倾河，
应合飞腾上谏坡。
富贵腥膻真梦耳，
死生名节奈君何。
欲求佳传无千斛，
但把青魂付九歌。
斗酒淋漓浇宿草，
西风老泪不胜多。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_219','吴夫人挽词','周紫芝','北宋末','懿德闺房重，
高名远近称。
流年忽成梦，
素节尚如冰。
法悟无生忍，
禅参最上乘。
应怜女博士，
空近读书灯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_220','吴夫人挽词','周紫芝','北宋末','素幔秋风急，
烟峰晓日残。
香沈金兽在，
镜掩玉台寒。
恩已沾封诰，
人空委佩兰。
他年作佳传，
谁为考幽刊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_221','李卿挽词','周紫芝','北宋末','东汉埋轮手，
开元御府卿。
名因射策早，
恩许故家荣。
竟失鹓行旧，
空乘马鬣旌。
他时双骥子，
万里是归程。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_222','桐川太守母夫人挽词','周紫芝','北宋末','夫人无复拥鱼轩，
旅榇归来倍黯然。
皂盖朱轓今有子，
布裙椎髻旧推贤。
馀哀尽入虞殡曲，
盛事当随列女篇。
忽掩幽墟可无恨，
诰封生享更高年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_223','哭吴与行二绝','周紫芝','北宋末','李广平生竟不侯，
功名看得鬓霜秋。
学无西洛时难偶，
人似南金价未酬。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_224','哭吴与行二绝','周紫芝','北宋末','投笔文场日未西，
春蚕食饱速于飞。
充庭不是无前列，
从此元江九肋稀。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_225','闻侯元进死','周紫芝','北宋末','薄宦时难得，
馀生老易分。
人言侯叔起，
诗学鲍参军。
未补胸中线，
空修地下文。
欲寻高密语，
应怕虎狼群。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_226','闻侯元进死','周紫芝','北宋末','君在漳溪病，
相逢特地欢。
句新诗屡出，
谈剧酒频寒。
梦作三春别，
人成隔世看。
无由吊尘几，
只有涕阑干。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_227','悼舒永丰','周紫芝','北宋末','舒侯九秋鹰，
未奋老拳翼。
平生流辈中，
肯数程不识。
庾公开幕府，
少作九江客。
风檐挂虚楼，
夜月浮大白。
饮气吞江流，
高谈倾坐席。
一朝胡尘暗，
孤垒困剧贼。
艨艟浮江下，
云雾蔽天赤。
坐中嘬炙儿，
相视无人色。
手持白羽扇，
奋身追危壁。
坐解两家难，
稍稍无勍敌。
身几落虎口，
名不挂赏籍。
鸟去良弓藏，
论功止投石。
岁晚犹折腰，
得邑亦甚僻。
似闻山中人，
尽饱太邱德。
官谤殊未明，
此责讵可塞。
乃复令斯人，
含恨入窀穸。
风亭分客袂，
仅作秋夏隔。
夺我玉面郎，
江湖坐愁寂。
抚棺欲三号，
何由反乡国。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_228','元具茨不起道州之疾哭之以诗','周紫芝','北宋末','一别鲁山三岁馀，
西来消息未全疏。
白头忍雪舂陵涕，
醉墨才乾庐阜书。
晚路得州真似斗，
平生弹铗竟无鱼。
漫郎犹有新书在，
千古风流不负渠。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_229','沈贵池挽词','周紫芝','北宋末','泽宫当日喜逢君，
鸡鹜初惊鹤在群。
果见廉平清似水，
不嫌名宦薄于云。
一区未买江边宅，
三尺谁浇陇上坟。
自古达人俱泯灭，
固应知有沈休文。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_230','李使君挽词三首','周紫芝','北宋末','治剧知公老更优，
何尝箕敛急征求。
谁言粟自关中漕，
但见钱从地上流。
已报南来三日政，
为宽北顾一时忧。
皇天自古无公道，
不遣刘郎到白头。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_231','李使君挽词三首','周紫芝','北宋末','溪头万杵响春雷，
谈笑争看雉堞开。
鼛鼓不须催昼急，
丽谯疑复自天来。
一樽谁酹风前酒，
万柳空垂雪后栽。
鲁史书城三十六，
不殚民力独公才。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_232','李使君挽词三首','周紫芝','北宋末','使君投老益精明，
三换鱼符寄一城。
汉相未曾除郡守，
蜀祠空复拜诸生。
他年宿草人谁吊，
当日清泉我作铭。
万里巴江消息断，
不堪斜日上寒旌。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_233','蔡氏夫人挽词','周紫芝','北宋末','中郎文采照当年，
妇德尤称女弟贤。
长夜忽成三尺垄，
异恩来自九重天。
名留仙籍谁能见，
事载铭诗世谩传。
想得伯鸾怀旧恨，
摩挲归榇一潸然。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_234','方桐川挽词','周紫芝','北宋末','善人沦没意如何，
细说平生恨转多。
此日飞腾只兰省，
当时准拟上銮坡。
十年犹记燕姬舞，
一曲今悲鬼伯歌。
欲问哭君多少泪，
未能注海亦倾河。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_235','周脩武挽词','周紫芝','北宋末','懒随车马著冠裳，
便筑华堂作醉乡。
遮眼不知山几叠，
供闲自有木千章。
平生阴德应无数，
他日高门未可量。
我亦元无谀墓手，
斯文聊付起家郎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_236','吊孙云老','周紫芝','北宋末','孙郎涉世似虚舟，
一醉从前万事休。
千佛经中无姓字，
八仙歌里见风流。
清诗便与重泉隔，
客泪空添晚岁愁。
陇上只今多宿草，
为君何地筑糟邱。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_237','哭二罗','周紫芝','北宋末','平生交友怀三益，
晚岁悲酸吊二罗。
地下忽埋双白璧，
人间真是一南柯。
篇章零落知谁管，
人物风流竟若何。
未有只鸡浇斗酒，
空令老泪作倾河。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_238','吊陈相之侍郎','周紫芝','北宋末','畴昔相逢十载馀，
已惊白雪鬓疏疏。
长鸣本是空群马，
入社犹为漏网鱼。
醉到湖边谁共酒，
别来江上苦无书。
风流文采今何在，
只有倾河泪满裾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_239','九道江中吊赵温叔','周紫芝','北宋末','昔饮江南酒，
刘郎鬓未华。
无依怜晚岁，
死贼痛全家。
梦隔泉台久，
魂归故国赊。
与谁山下路，
同折冻梅花。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_240','大宋中兴颂','周紫芝','北宋末','缅维圣宋，
昔在中叶。
四方多虞，
万里喋血。
大臣持谋，
兴师肆伐。
将臣持兵，
日献戎捷。
皇帝曰吁，
黩武无烈。
糜我赤子，
膏我斧钺。
孰与休师，
一戟不折。
因垒而降，
舞干而悦。
闭我玉关，
归师解甲。
犁我春田，
销兵铸铁。
使命交通，
相望不绝。
爱惜两朝，
前师圣说。
昭陵之仁，
嘉祐之业。
念昔兴师，
堂陛卼臲。
发言盈庭，
更訾元蔑。
佩剑彼此，
孰予孰决。
庙谋一定，
群议沮折。
袖手何言，
瞠目卷舌。
草木苍苍，
始有芽蘖。
尽育恢胎，
咸归坱圠。
灞上棘门，
环卫拱列。
罔敢擅师，
始制君节。
万夫属鞬，
拜舞君阙。
乃命叔孙，
诹日绵蕝。
蒐讲阙遗，
悉究悉设。
皇帝孝思，
上与天合。
冀获一真，
如响必答。
翠舆南旋，
红鸾秉翣。
长乐钟闻，
皇情允惬。
我歌思齐，
舆情激越。
皇帝之祀，
咸秩罔缺。
合祭于郊，
爰胾茧栗。
苍璧前陈，
大裘始挈。
我歌思文，
以告丰洁。
大庆御朝，
王春正月。
禹会涂山，
万玉交戛。
汉朝诸侯，
图籍是阅。
兵戈澒洞，
士气销詟。
俎豆不陈，
军旅是急。
大起廱泮，
儒士鼓箧。
韦带缟衣，
骈冠累屧。
论秀蒸髦，
尾尾岌岌。
农流于兵，
病不生活。
茫茫千塍，
蒿藜是没。
皇帝慨然，
亲耕陇畷。
耕根之车，
飞檐䡾䡾。
宣和之轨，
明道之辙。
圣心恳到，
三推未辍。
父老曰嘻，
归告我邑。
俾尔粳稌，
屯云积雪。
凡此大功，
具载史牒。
用告神明，
以报夔契。
帝坐法宫，
礼备乐阕。
兽舞凤鸣，
八音不夺。
皇威所覃，
雷动风发。
南面垂衣，
大壮帝室。
曰皋曰雉，
鼛鼓弗及。
苍龙之阙，
上摩星日。
万目顾瞻，
葱葱郁郁。
澎澎海潮，
吴会来集。
天子万年，
风翔喜溢。
孰磨苍崖，
孰秉史笔。
天子曰都，
是任良弼。
圣有至言，
维德之一。
是用作歌，
以告万国。',NULL,'','{"preface": "窃惟毛诗一经，三百六篇。其间咏盛德而赞成功者，殆居其半。圣经所载，宁有愧辞？将上以昭格于神灵，下以垂芳于奕世，俾诵其言者信其事，为万世之龟鉴，岂曰小补之哉！粤维炎宋，国步中艰，笃生圣神，克绍远烈。尊用元臣，以扶昌运。寝兵以来，海内清平，文章华焕。考之诗书，皆所未有。夫舜有大功，不过二十而止。神禹丕绩，唯闻九叙之歌。今皇帝殄攘浮议，剪剔奸雄。和附乖离，敉宁区夏。至于迎母后于遐方，礼天神于圆陛，拜原庙之衣冠，纳春朝之图籍；以至灵台歌辟廱之乐，载芟草藉田之颂，凡一礼一乐有所未备，必蒐订遗文，以补罅漏。自其纤悉，驯致大功。方之舜禹，未或远过。顾惟寒生，均与斯民。蒙被圣泽，敢作颂诗，以申歌咏。虽记问空疏，文辞浅颣，不能远追王褒乐职之诗，近配宗元淮西之雅，犹足曳履行歌，为太平之幸民，亦庶几采诗之官，尚或有取。颂曰：", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_8_241','天申节乐语口号','周紫芝','北宋末','建章宫殿拥祥烟，
遥望需云锡御筵。
上帝自应知舜孝，
万方宜共祝尧年。
苍龙阙转曈昽日，
瑞兽香闻咫尺天。
湛露恩深何以报，
愿将虎拜答周宣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_242','周朝议宣新第致语口号','周紫芝','北宋末','风光浑占一溪中，
青谷新开甲第雄。
凉榭切云先得月，
朱楼凌水欲横空。
连甍万瓦琉璃碧，
照坐千钟琥珀红。
要看仍云乘驷马，
使君眉寿似乔松。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_243','上元燕宾客致语口号','周紫芝','北宋末','使君才气本无双，
暂拥州麾殿大邦。
千骑出城闻画角，
万灯衔壁看银釭。
夜天星满光浮汉，
秋水花红锦照江。
莫向华堂辞一醉，
君正怀旧忆奇庞。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_244','燕太守汪内相致语口号','周紫芝','北宋末','谁持尺一下明光，
新易泉南旧印章。
禁殿何时出颇牧，
人间又喜见龚黄。
攀辕父老今犹在，
骑竹儿童喜欲狂。
只恐政成归更速，
便纡华衮望清光。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_245','燕吴奉使致语口号','周紫芝','北宋末','清诏名高下紫宸，
异方初喜见王人。
二年辇毂辞家远，
万里岷峨入眼新。
使者登车争揽辔，
君王问俗颇忧民。
翰林劝酒非无意，
知向明光作侍臣。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_246','二妙堂落成家集致语口号','周紫芝','北宋末','居士归来已白头，
数椽聊喜枕江流。
百年梦幻何时了，
二妙江山一日收。
鼓吹自从诗里得，
光阴都在醉中休。
蟹螯霜后偏宜酒，
苏幕歌成可共讴。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_247','松林道人施绣观音','周紫芝','北宋末','菩萨变化如虚空，
云何得此虚空相。
我观无碍大慈悲，
无刹不现如水月。
八万四千母陁臂，
能援世间一切众。
八万四千清净眼，
能照五浊诸有情。
是故神通不思议，
而欲妄以色相求。
譬如狂人逐四方，
四方无尽力无竭。
况以丹青绘缯䌽，
更复刺绣为仪形。
丝毫缣素相假合，
妙技巧借金十奴。
若人捐弃钋与丝，
亦无五色可资藉。
瞑目默相不可得，
毕竟无有是菩萨。
吾愿世人舍色相，
当时未有钋丝时。
蓬莱观妙本无心，
以粗即妙作是念。
松林无心受此施，
以施居士作礼言。
我当还亦以此施，
此施有尽法无穷。
普愿世间诸佛子，
凡瞻此相悉欢喜。
若见菩萨非菩萨，
即知是我非是妄。
妄见除灭无复然，
吾与佛子等无二。',NULL,'','{"preface": "蓬莱夫人以欢喜心而作佛事，于是刺绣为观音像，极诸相好，施松林师。庄严奇丽，非世所能。如五色云，未尝彩绘，自然成文。烂然盈月，如虚空日。不加磨砻，自然光明。照耀十方，如西蜀锦。文与质成，以文名锦。是锦非文，孰知因文而以名锦？如出水莲，华干俱生，以华名莲。是莲非华，孰知因华而以名莲？则是菩萨以幻而成，诸着相者亦以幻想，孰知因想以名菩萨？维观世音以大慈悲随现说法，变化无穷，满恒河沙界。不应此施留恋执著，使彼见者愿乐工巧。双溪道人作是语已，松林老师释然而喜，还以此施回施道人，于是稽首而作偈言：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_248','梦礼僧伽大士','周紫芝','北宋末','我观诸佛子，
皆以妄自冥。
不知有无想，
一切俱是妄。
认有以为实，
夫岂识无有。
如人具诸欲，
耳目与鼻舌。
百体俱动作，
动作皆有相。
耳欲以听声，
有耳言可闻。
弦匏与笙箫，
皆具诸宫羽。
虽然始一奏，
有耳悉皆闻。
众生于是时，
知声不知耳。
众音始一阕，
寂静无有声。
倾耳而听之，
无一可闻者。
众生于是时，
知耳不知声。
至于目视色，
亦复如耳根。
知色为有形，
乃以色为有。
宁知本无色，
何况于目睫。
乃至鼻闻臭，
口舌所啖食。
百体诸毛发，
意有所为者。
行步与坐卧，
喘息及呼吸。
方其有为时，
无一不为有。
诸为悉皆空，
了无有一存。
心惟昨所为，
恍惚如梦事。
我昔礼菩萨，
是为真见者。
譬如闻众声，
认声为有响。
比其不及礼，
菩萨那得见。
譬如众声灭，
初不闻馀音。
始缘以妄情，
乃复有见否。
亦如今所梦，
见否理不殊。
大士笑不言，
吾亦无所说。
有如舍利佛，
默默对天女。
稽首作偈言，
犹以言为痛。
云何两无言，
而入不二门。
我与诸佛子，
究竟得成道。',NULL,'','{"preface": "岁在丁酉冬至后一日，某西游大梁，取道泗滨。翌日礼僧伽大士塔而行。明年春东归，复过之，以故迫于亟去，不复作礼，私心怏怏，常若慊然。其后百二十有六日，夜梦拜塔下，瞻望圣像而祷焉，曰：顷以故不能来，今以何力而至？大士笑而不言。于是既寤，叹曰：菩萨以无心而应物，居士以无心而作礼。初无分于寤寐，有缘而来，无缘而去，等为一梦，有何差殊？人能以一切无心付诸缘于幻化，斋寤寐于俄顷，则我菩萨与诸佛子皆得成佛，是无难者。于是乃始稽首忏悔而作偈言：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_249','宗演师金书妙法莲经','周紫芝','北宋末','稽首无上尊，
为世大慈父。
为悯一切众，
流浪诸苦海。
滋无碍辨才，
广为众生说。
譬如大火宅，
随念得清凉。
又令诸穷子，
获此大宝珠。
是真秘密藏，
故名妙法华。
非思量分别，
而以得解悟。
虽诸大菩萨，
有所不能知。
况于声闻众，
岂复闻妙义。
如来广开示，
一一令悟入。
众生悉皆晓，
而况于声闻。
我佛出现世，
了此一大缘。
当如佛所说，
是最为第一。
今此大比邱，
舍所甚爱者。
百炼真黄金，
销铄为书写。
具诸大宝贝，
更以为庄严。
偷儿甚魁侩，
如飞天药叉。
诸所经过处，
悉为尸陁林。
大火所藏灭，
毫发无遗馀。
龙天诸善神，
悉力来加护。
究竟不得坏，
我今同赞叹。
普告诸佛子，
凡所见闻者。
信心自坚固，
各各普授持。',NULL,'','{"preface": "昔泾水西有大道场，赐号崇庆，中有苾刍，名曰宗演，具善知识，受具出家。以清净心降伏诸魔，以精进书萨达磨奔茶利迦素咀缆文，成一大部，缄以缥囊，贮以宝函，具诸庄严，供养受持。尔时南方群盗遍起，诸比丘众悉皆惊怖逃难云散，不知是经复在何处。及诸盗已，一切诸有悉皆坏灭，独是经典或在地上，或在他方。得是经者各持所得而以来献，如是者三。经大火聚，度无量厄，究竟不坏，诸所染污及所漫阙毫发无有。于是比丘欢喜踊跃，叹未曾有。吾时避难在泾水西，目见是事，同一赞叹，而说偈言：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_250','金刚般若波罗密经','周紫芝','北宋末','佛以甚深微妙法，
广为一切众生说。
有能悉发菩提心，
究竟得成无上道。
彼有受持读诵者，
其福不可更称量。
七宝满尔河沙数，
以用布施得福德。
而比福德犹为多，
况吾大慈大愿师，
常悯众生堕恶道。
假此持经功德海，
能免世间一切苦。
有大长者号宰官，
书写读诵不少懈。
旃檀香及薝卜花，
供养恭敬常作礼。
忽遇黑风吹船舫，
将随那刹诸鬼国。
仓惶取是受持经，
投诸江流没巨浪。
须臾风定夜色霁，
达旦悉得大快乐。
平明篙师有妇妻，
忽言汲水得巨轴。
金书贝叶与巾绣，
无一毫毛有坏相。
有如金刚不坏身，
经大水聚性不灭。
拾尘数劫有时尽，
而是功德终无穷。
众生信心不坚固，
未尝闻此殊胜事。
用是稽首无上尊，
愿我诸佛常加护。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_251','戏作小诗用少陵事','周紫芝','北宋末','百尺寒松老干枯，
韦郎笔妙古今无。
何如莫扫鹅溪绢，
留取天吴紫凤图。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_252','句','周紫芝','北宋末','枕簟绿阴花谢后，
轩窗清景月明时。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_8_253','句','周紫芝','北宋末','浪花丛里看蟂矶。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_8_254','句','周紫芝','北宋末','秋声归草木，
寒色到衣裘。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_8_255','句','周紫芝','北宋末','江南树树黄垂蜜。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_8_256','附录 元祐元年己巳正月三十日同太史薄达夫来游概作六咏又作长篇以广其意景尔','周紫芝','北宋末','灵岩胜概魁宁川，
欲往还心几踰年。
今朝乘兴得清赏，
须知亦是同夤缘。
驱车初抵石门路，
恍疑共到蓬莱天。
旁连高延立玉壁，
下广迤逦铺琼田。
俄从一径造佛刹，
楼阁深耸凌云烟。
山僧指我遍幽历，
崄巇不惮跻山颠。
明心深邃光通穿，
朝阳晴晖火欲然。
涟漪澄澈渚寒泉，
碧云紫雾争华鲜。
夕阳林麓禽啾喧，
尝闻昔有瞿硎仙。
我今不见心悬悬，
广寒宫阙名空传。
日暮欲去还留连，
嗟予事夺须回旋。
不得共宿高谈禅，
邮亭耿耿夜不眠。
拥衾操笔成长篇，
封题远寄风骚贤。
辞语芜陋不足道，
爝火妄记星光躔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_257','和菊花','朱胜非','宋','纷纷桃李春，
过眼成枯萎。
晚荣方耐久，
造物岂吾欺。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_258','和同省秋省宿','朱胜非','宋','老火未甘退，
稚金方力征。
炎凉分胜负，
顷刻变阴晴。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_259','浦溪','朱胜非','宋','郴岭最高处，
桐轩临水开。
晚晴东北望，
直见郁孤台。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_8_260','天圣寺古桧','朱胜非','宋','雷霆起蛰虬，
夭矫势欲上。
忽然化此木，
尚作拿云状。
婆娑枝干垂，
生涩纽结壮。
图经不能记，
父老那可访。
晋杉定侪类，
蜀柏岂辈行。
栎梦何足神，
槐语固已妄。
自无斧斤忧，
未始疑大匠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_261','泸渡','朱胜非','宋','曾到泸溪渡，
山青石壁粗。
云藏天宝塔，
水绕率岩湖。
日暖鱼增价，
风和酒易沽。
鱼船交过往，
商旅及成都。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_8_262','石通洞','朱胜非','宋','涪翁诗名存宇宙，
李杜摧锋君殿后。
山川草木经品题，
千古佳名长不朽。
中年微累黔中□，
石通曾运羲□□。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_8_263','句','朱胜非','宋','始意钟陵参马祖，
却寻橘井访苏仙。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_8_264','句','朱胜非','宋','地藏堂中坐，
